#!/usr/bin/env node
// Any-number conformance fixtures: the bytes Yjs writes for a Number at each
// edge of lib0's writeAny dispatch. lib0 writes tag 125 while |v| <= 2^31-1,
// then tag 124 when a float32 holds v exactly, else tag 123. Each row is a
// one-item YArray pushed by a document with a pinned clientID, as V1 and V2
// hex, and the array's JSON as Yjs prints it. crdt/any_number_js_compat_test.go
// pushes the same number from Go, as each Go integer type that holds it, and
// must write these bytes; it also applies them and must print that JSON.
// Regenerated by `make fixtures`; the CI drift gate fails if committed bytes
// diverge.
const Y = require('yjs')
const fs = require('fs')
const path = require('path')

const outFile = path.join(__dirname, '..', 'crdt', 'testdata', 'anynumber_yjs_fixtures.json')
const hex = (u8) => Buffer.from(u8).toString('hex')

const numbers = [
	['2^31-1', 2 ** 31 - 1],
	['-(2^31-1)', -(2 ** 31 - 1)],
	['2^31', 2 ** 31],
	['-2^31', -(2 ** 31)],
	['2^31+1', 2 ** 31 + 1],
	['-2^31-1', -(2 ** 31) - 1],
	['3*2^35', 3 * 2 ** 35],
	['2^40', 2 ** 40],
	['-2^40', -(2 ** 40)],
	['2^53-1', 2 ** 53 - 1],
	['2^53', 2 ** 53],
	['-2^53', -(2 ** 53)],
	['2^63', 2 ** 63],
	// The Number a Go uint64 of math.MaxUint64 becomes.
	['2^64', 2 ** 64],
]

const rows = numbers.map(([name, n]) => {
	const doc = new Y.Doc()
	// Y.Doc's constructor takes no clientID; pin it so every run writes the
	// same bytes.
	doc.clientID = 1
	const a = doc.getArray('a')
	a.push([n])
	return {
		name,
		v1: hex(Y.encodeStateAsUpdate(doc)),
		v2: hex(Y.encodeStateAsUpdateV2(doc)),
		json: JSON.stringify(a.toJSON()),
	}
})

fs.writeFileSync(outFile, JSON.stringify(rows, null, 2) + '\n')
console.log(`wrote crdt/testdata/anynumber_yjs_fixtures.json (${rows.length} numbers)`)
